{"command": "python3 << 'PYEOF'
import subprocess
import json

for p in [2, 3, 6]:
    for r in [0, 8, 16, 24]:
        result = subprocess.run(['ft2', 'call', 'pattern_get_cell', json.dumps({'pattern': p, 'row': r, 'channel': 4})], capture_output=True, text=True)
        data = json.loads(result.stdout)
        cell = json.loads(data['content'][0]['text'])
        print(f"P{p} R{r} Ch4: note={cell['note']}, inst={cell['instrument']}, vol={cell['volume']}")
PYEOF"}

