{"command": "python3 << 'PYEOF'
import subprocess
import json

for p in [2, 3, 6]:
    for ch in range(8):
        result = subprocess.run(['ft2', 'call', 'pattern_get_cell', json.dumps({'pattern': p, 'row': 0, 'channel': ch})], capture_output=True, text=True)
        data = json.loads(result.stdout)
        cell = json.loads(data['content'][0]['text'])
        if cell['note'] > 0 or cell['instrument'] > 0:
            print(f"P{p} Ch{ch}: note={cell['note']}, inst={cell['instrument']}, vol={cell['volume']}")
    print("---")
PYEOF"}

